#nullable enable // autogenerated

using System.Xml;
using MVZ2.IO;
using MVZ2Logic.Resources;
using PVZEngine;
using PVZEngine.Tools.Unity;

namespace MVZ2.Metas
{
    public class CustomizePageMeta
    {
        public CustomizePageMeta(string id)
        {
            ID = id;
        }

        public string ID { get; private set; }
        public string ButtonText { get; private set; } = string.Empty;
        public NamespaceID? PrefabPath { get; private set; }
        public XMLConditionList? Unlock { get; private set; }
        public static CustomizePageMeta? FromXmlNode(XmlNode node, string defaultNsp)
        {
            var id = node.GetAttribute("id");
            if (string.IsNullOrEmpty(id))
            {
                Log.LogError($"The ID of a {nameof(CustomizePageMeta)} is invalid.");
                return null;
            }
            var buttonText = node.GetAttribute("buttonText") ?? string.Empty;
            var prefabPath = node.GetAttributeNamespaceID("prefabPath", defaultNsp);
            XMLConditionList? unlocks = null;
            var unlockNode = node["unlock"];
            if (unlockNode != null)
            {
                unlocks = XMLConditionList.FromXmlNode(unlockNode, defaultNsp);
            }
            return new CustomizePageMeta(id)
            {
                ButtonText = buttonText,
                PrefabPath = prefabPath,
                Unlock = unlocks
            };
        }
    }
}
